#include <iostream>

void incByValue(int n) {
    ++n;
}

void incByRef(int& n) {
    ++n;
}

void incByPtr(int* p) {
    if (p == nullptr) {
        return;
    }
    ++*p;
}

int valueOr(const int* p, int fallback) {
    if (p) {
        return *p;
    }
    return fallback;
}

int main() {
    int count = 0;
    incByValue(count);
    std::cout << count << ' ';
    incByRef(count);
    std::cout << count << ' ';
    incByPtr(&count);
    std::cout << count << ' ';
    incByPtr(nullptr);
    std::cout << count << '\n';

    std::cout << valueOr(&count, -1) << ' ' << valueOr(nullptr, -1) << '\n';
    return 0;
}

