#include <iostream>

int countAbove(const int* arr, int n, int limit) {
    int count = 0;
    for (const int* p = arr; p != arr + n; ++p) {
        if (*p > limit) {
            ++count;
        }
    }
    return count;
}

int main() {
    int scores[4] = {70, 95, 82, 61};
    const char* word = "pointer";

    for (const int* p = scores; p != scores + 4; ++p) {
        if (p != scores) {
            std::cout << ' ';
        }
        std::cout << *p;
    }
    std::cout << '\n';

    std::cout << *(scores + 1) << ' ' << scores[1] << '\n';
    std::cout << countAbove(scores, 4, 80) << '\n';

    int vowels = 0;
    for (const char* c = word; *c != '\0'; ++c) {
        if (*c == 'a' || *c == 'e' || *c == 'i' || *c == 'o' || *c == 'u') {
            ++vowels;
        }
    }
    std::cout << word << ' ' << vowels << '\n';
    return 0;
}
